package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.os.Bundle;import android.provider.CalendarContract;import android.database.Cursor;import android.widget.*;import org.json.*;import java.util.*;

/** All four areas consume a single owned GoalContext and repository. */
public class CharacterWorkspaceActivity extends GoalUi {
 GoalStore store;TaskStore tasks;JSONObject g;GoalRules.Preset preset;String gid;int tab;String needId="";AlertDialog checkoutDialog;
 public void onCreate(Bundle b){super.onCreate(b);store=new GoalStore(this);tasks=new TaskStore(this);gid=getIntent().getStringExtra("goal_id");try{g=store.goal(gid);}catch(Exception e){finish();return;}preset=GoalRules.preset(g.optString("character"));tab=getIntent().getIntExtra("tab",g.optInt("tab",0));needId=getIntent().getStringExtra("need_id");if(needId==null)needId="";store.event(gid,"workspace_opened");render();}
 protected void onResume(){super.onResume();if(store!=null&&gid!=null){try{g=store.goal(gid);render();}catch(Exception e){finish();}}}
 String query(){return GoalRules.query(preset.id,g.optBoolean("motivation",true),g.optBoolean("information",true),g.optString("topic"),g.optString("language","ko"));}
 void render(){int oldY=scroll==null?g.optInt("scroll"+tab,0):scroll.getScrollY();frame(preset.name+"의 작업실","목표와 탐색을 한곳에");LinearLayout h=card();hero(h,preset,g.optString("title"));action(h,"목표·개인화 설정",this::settings);LinearLayout tabs=new LinearLayout(this);String[] names={"미디어 탐색","구매·알림","함께하는 사람들","캘린더·도구"};for(int i=0;i<names.length;i++){final int n=i;Button b=button(names[i],tab==i);b.setTextSize(12);b.setOnClickListener(v->{GoalStore.put(g,"scroll"+tab,scroll.getScrollY());tab=n;GoalStore.put(g,"tab",n);store.saveGoal(g);render();scroll.post(()->scroll.scrollTo(0,g.optInt("scroll"+tab,0)));});tabs.addView(b,new LinearLayout.LayoutParams(0,Ui.dp(this,56),1));}body.addView(tabs,Ui.match(this,-2,14));if(tab==0)media();else if(tab==1)commerce();else if(tab==2)people();else calendar();LinearLayout assist=card();note(assist,preset.name+": 오늘은 탐색부터 해도 좋아. 필요한 것만 목표에 담아봐.");action(assist,"목표 안에서 찾을 내용 입력",()->{LinearLayout p=Ui.vertical(this,BG,16);EditText q=edit(p,"찾고 싶은 공개 정보",g.optString("topic"));new AlertDialog.Builder(this).setTitle("검색 주제 바꾸기 · 규칙 기반").setView(p).setNegativeButton("취소",null).setPositiveButton("적용",(d,w)->{String t=q.getText().toString().trim();if(t.length()>80||t.isEmpty()){toast("주제를 1~80자로 입력해줘.");return;}GoalStore.put(g,"topic",t);store.saveGoal(g);tab=0;render();}).show();});scroll.post(()->scroll.scrollTo(0,oldY));}
 void settings(){LinearLayout p=Ui.vertical(this,BG,18);EditText title=edit(p,"목표 제목",g.optString("title")),topic=edit(p,"공개 검색 주제",g.optString("topic")),budget=edit(p,"예산 (원)",Long.toString(g.optLong("budget")));budget.setInputType(2);CheckBox m=new CheckBox(this),i=new CheckBox(this);m.setText("자극·동기부여");i.setText("정보·방법 배우기");m.setChecked(g.optBoolean("motivation",true));i.setChecked(g.optBoolean("information",true));p.addView(m);p.addView(i);Spinner language=new Spinner(this);language.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"한국어","영어"}));language.setSelection(g.optString("language").equals("en")?1:0);p.addView(language);note(p,"규칙 기반 검색어에 선택한 목적과 언어를 반영해. 두 목적을 모두 끄면 검색을 멈춰.");new AlertDialog.Builder(this).setTitle("목표 설정").setView(p).setNegativeButton("취소",null).setNeutralButton("목표 삭제",(d,w)->new AlertDialog.Builder(this).setTitle("연결된 기록과 일정을 지울까?").setNegativeButton("취소",null).setPositiveButton("삭제",(a,z)->{tasks.getWritableDatabase().delete("tasks","goal_id=?",new String[]{gid});store.deleteGoal(gid);finish();}).show()).setPositiveButton("저장",(d,w)->{try{String t=title.getText().toString().trim(),q=topic.getText().toString().trim();long v=Long.parseLong(budget.getText().toString());if(t.isEmpty()||t.length()>100||q.length()>80||v<0)throw new Exception();GoalStore.put(g,"title",t);GoalStore.put(g,"topic",q);GoalStore.put(g,"budget",v);GoalStore.put(g,"motivation",m.isChecked());GoalStore.put(g,"information",i.isChecked());GoalStore.put(g,"language",language.getSelectedItemPosition()==1?"en":"ko");GoalStore.put(g,"version",g.optInt("version",1)+1);store.saveGoal(g);render();}catch(Exception e){toast("입력한 제목·주제·예산을 확인해줘.");}}).show();}
 void media(){LinearLayout p=card();p.addView(txt("발견하는 시간",23,INK,true));String q=query();note(p,q.isEmpty()?"자극·동기부여 또는 정보·방법을 하나 이상 선택해줘.":"규칙 기반 검색어: "+q);if(q.isEmpty())return;
  action(p,"YouTube 영상·채널 탐색",()->discover("youtube",q,""));
  action(p,"뉴스·글 새로 가져오기",()->{if(isFinishing())return;MediaRepository.fetch(this,store,gid,q,g.optString("language","ko"),g.optBoolean("recent",true),msg->{if(!isFinishing()){toast(msg);g=store.goal(gid);render();}});});
  action(p,"웹 글 탐색",()->discover("naverweb",q,""));
  action(p,"상세 필터",()->{String[] opts={"최신 뉴스 우선 (7일 검색)","저장한 콘텐츠만 보기"};boolean[] c={g.optBoolean("recent",true),g.optBoolean("savedOnly",false)};new AlertDialog.Builder(this).setTitle("상세 필터").setMultiChoiceItems(opts,c,(d,n,v)->c[n]=v).setPositiveButton("적용",(d,w)->{GoalStore.put(g,"recent",c[0]);GoalStore.put(g,"savedOnly",c[1]);store.saveGoal(g);render();}).show();});
  note(p,"Threads: auth_required · Instagram/Reels: permission_required. 개인 피드는 연결하지 않았어. 아래 결과는 제목·메타데이터만 읽었어.");
  note(p,"뉴스 상태: "+g.optString("newsStatus","아직 조회하지 않음")+" · 마지막 확인 "+g.optString("newsChecked","없음"));
  int count=0;List<JSONObject> content=store.contents(gid,q,g.optBoolean("savedOnly"));content.sort((a,z)->Long.compare(z.optLong("checkedAt"),a.optLong("checkedAt")));
  for(JSONObject c:content){count++;LinearLayout item=card();item.addView(txt(c.optString("title"),19,INK,true));note(item,c.optString("provider")+" · "+c.optString("kind")+" · "+c.optString("author","작성자 미확인"));note(item,"게시: "+c.optString("published","미확인")+" / 확인: "+new java.util.Date(c.optLong("checkedAt")));note(item,"추천 이유: 목표 검색어에 포함된 공개 검색 결과 · "+(g.optBoolean("motivation")?"동기부여 ":"")+(g.optBoolean("information")?"정보":"")+" (검색 목적, 내용 판정 아님)");action(item,"원문에서 보기",()->open(c.optString("url")));action(item,c.optBoolean("saved")?"저장 취소":"저장",()->{GoalStore.put(c,"saved",!c.optBoolean("saved"));store.save("contents",gid,c);store.event(gid,"media_saved");render();});action(item,"관심 없음",()->{GoalStore.put(c,"hidden",true);store.save("contents",gid,c);store.event(gid,"media_hidden");render();});action(item,"비슷한 콘텐츠",()->discover(c.optString("provider").equals("YouTube")?"youtube":"naverweb",c.optString("title").substring(0,Math.min(60,c.optString("title").length())),""));action(item,"목표에 적용 · 일정 초안",()->taskDraft(c));if(!preset.id.equals("home")&&c.optString("title").matches(".*(준비물|장비|기구|홈트|매트|선물|보드게임|플래너).*"))action(item,"관련 준비물 확인",()->needDraft(c));}
  if(count==0){LinearLayout e=card();note(e,"아직 이 검색 조건으로 가져온 콘텐츠가 없어. 위에서 실제 사이트를 탐색하거나 뉴스를 가져와줘.");}
 }
 void needDraft(JSONObject content){LinearLayout p=Ui.vertical(this,BG,16);EditText purpose=edit(p,"무엇에 쓰려고 해?",g.optString("title")),item=edit(p,"비교할 준비물",preset.item),owned=edit(p,"이미 가지고 있는 물건","");note(p,"콘텐츠에 이 상품이 등장했다는 의미는 아니야. 보유한 물건으로 진행할 수 있으면 구매하지 않아도 좋아.");new AlertDialog.Builder(this).setTitle("정말 필요한지 먼저 확인하자").setView(p).setNegativeButton("이미 있어 · 취소",null).setPositiveButton("비교해줘",(d,w)->{if(item.getText().toString().trim().isEmpty())return;JSONObject n=new JSONObject();GoalStore.put(n,"sourceId",content==null?"":content.optString("id"));GoalStore.put(n,"purpose",purpose.getText().toString());GoalStore.put(n,"query",item.getText().toString());GoalStore.put(n,"owned",owned.getText().toString());GoalStore.put(n,"budget",g.optLong("budget"));GoalStore.put(n,"confirmation","compare_requested");GoalStore.put(n,"reason","사용자가 준비물 비교를 요청함");needId=store.save("needs",gid,n);store.event(gid,"need_confirmed");tab=1;GoalStore.put(g,"tab",1);store.saveGoal(g);render();}).show();}
 void commerce(){LinearLayout p=card();p.addView(txt("필요한 것만, 조건을 보고",23,INK,true));action(p,"준비물 필요 확인",()->needDraft(null));JSONObject need=null;for(JSONObject n:store.list("needs",gid)){if(need==null||n.optString("id").equals(needId))need=n;}String q=need==null?preset.item:need.optString("query");final String nid=need==null?"":need.optString("id");note(p,"비교 주제: "+q+" · 예산 "+g.optLong("budget")+"원 (0은 미설정)");if(need!=null)note(p,"사용 목적: "+need.optString("purpose")+" · 이미 보유: "+need.optString("owned"));
  action(p,"상품 · 네이버쇼핑 탐색",()->discover("navershop",q,nid));action(p,"상품 · 11번가 탐색",()->discover("11st",q,nid));action(p,"상품 · 쿠팡 탐색",()->discover("coupang",q,nid));action(p,"전문가·강의 찾기",()->discover("inflearn",preset.topic,nid));note(p,"토스쇼핑: unsupported (공개 소비자 검색 연동 미확보). 표시 가격·배송비가 확인된 조건만 비교해. 알 수 없는 배송비는 0원으로 세지 않아.");
  List<JSONObject> offers=store.list("offers",gid);offers.sort((a,z)->{Long x=offerTotal(a),y=offerTotal(z);return x==null?(y==null?0:1):y==null?-1:Long.compare(x,y);});int count=0;for(JSONObject o:offers){if(!nid.equals(o.optString("needId")))continue;count++;LinearLayout c=card();c.addView(txt(o.optString("title"),18,INK,true));Long total=offerTotal(o);note(c,o.optString("provider")+" · "+o.optString("priceText","가격 미확인")+" · 배송 "+o.optString("shippingText","미확인"));note(c,"결제 총액: "+(total==null?"미확인":total+"원")+" · 동일 상품·옵션 일치 미검증 / 대체 후보");note(c,"광고 여부: "+o.optString("sponsored","미확인")+" · 확인 "+new Date(o.optLong("checkedAt")));action(c,"판매처 상품에서 조건 확인",()->open(o.optString("url")));action(c,"주문 초안 · 구매 이어가기",()->checkout(o));action(c,"가격 알림 조건 저장",()->alert(o));}
  if(count<2)note(p,"현재 후보 "+count+"개. 두 판매처 이상의 동일 조건 오퍼가 없어 가격 비교 완료로 표시하지 않아.");else note(p,"후보 "+count+"개를 모았어. 제품·옵션·배송 조건이 달라 동일 상품 최저가로 합치지 않았어.");
  for(JSONObject intent:store.list("intents",gid)){LinearLayout c=card();note(c,"구매 의도: "+intent.optString("title")+" · "+intent.optString("state"));if(intent.optString("state").equals("handed_off"))note(c,"판매처로 이동했어. 실제 구매 결과는 아직 몰라.");if(intent.optString("state").equals("draft")||intent.optString("state").equals("awaiting_confirmation"))action(c,"구매 초안 다시 확인",()->resumeCheckout(intent));action(c,"직접 구매했다고 표시",()->{GoalStore.put(intent,"state","self_reported");store.save("intents",gid,intent);store.event(gid,"purchase_self_reported");render();});}
  for(JSONObject a:store.list("alerts",gid)){LinearLayout c=card();note(c,"수동 재조회 알림 조건 · "+a.optLong("threshold")+"원 이하 · 자동 감시 없음");action(c,"조건 해제",()->{store.remove("alerts",gid,a.optString("id"));render();});}
 }
 Long offerTotal(JSONObject o){if(!o.optBoolean("conditionsVerified")||!o.has("fees"))return null;return GoalRules.total(o.has("price")?o.optLong("price"):null,o.has("shipping")?o.optLong("shipping"):null,o.optLong("fees"),0L);}
 void alert(JSONObject o){LinearLayout p=Ui.vertical(this,BG,16);EditText e=edit(p,"원하는 총액 (원)","");e.setInputType(2);note(p,"기본 OFF. 조건 저장만 지원하며, 앱 종료 후 가격 감시·푸시는 아직 없어. 직접 다시 조회해야 해.");new AlertDialog.Builder(this).setTitle("수동 재조회 조건 저장").setView(p).setNegativeButton("취소",null).setPositiveButton("조건 저장",(d,w)->{try{long v=Long.parseLong(e.getText().toString());if(v<=0)throw new Exception();JSONObject a=new JSONObject();GoalStore.put(a,"offerId",o.optString("id"));GoalStore.put(a,"threshold",v);GoalStore.put(a,"enabled",false);GoalStore.put(a,"mode","manual_only");store.save("alerts",gid,a);render();}catch(Exception ex){toast("금액을 확인해줘.");}}).show();}
 void resumeCheckout(JSONObject intent){for(JSONObject offer:store.list("offers",gid))if(offer.optString("id").equals(intent.optString("offerId"))){checkout(offer);return;}toast("상품 후보를 다시 조회한 뒤 조건을 확인해줘.");}
 void checkout(JSONObject o){
  if(!GoalRules.safe(o.optString("url"))||checkoutDialog!=null&&checkoutDialog.isShowing())return;
  String fingerprint=o.optString("url")+"|"+o.optString("priceText")+"|"+o.optString("checkedAt");JSONObject existing=null;
  for(JSONObject x:store.list("intents",gid))if(fingerprint.equals(x.optString("offerVersion"))){String state=x.optString("state");if(!state.equals("draft")&&!state.equals("awaiting_confirmation")){toast("이미 판매처로 이동한 초안이야. 판매처에서 결과를 먼저 확인해줘.");return;}existing=x;break;}
  final JSONObject i=existing==null?new JSONObject():existing;
  if(existing==null){GoalStore.put(i,"title",o.optString("title"));GoalStore.put(i,"offerId",o.optString("id"));GoalStore.put(i,"offerVersion",fingerprint);GoalStore.put(i,"idempotencyKey",UUID.randomUUID().toString());}
  GoalStore.put(i,"state","awaiting_confirmation");store.save("intents",gid,i);
  checkoutDialog=new AlertDialog.Builder(this).setTitle("판매처에서 구매 계속하기").setMessage(o.optString("title")+"\n표시 가격: "+o.optString("priceText","미확인")+"\n옵션·수량·배송비·최종 총액은 판매처에서 다시 확인해줘. 이 동작은 주문·결제를 실행하지 않아.").setNegativeButton("취소",null).setPositiveButton("상품 화면으로 이동",(d,w)->{GoalStore.put(i,"state","handed_off");GoalStore.put(i,"handedAt",System.currentTimeMillis());store.save("intents",gid,i);store.event(gid,"checkout_handoff");open(o.optString("url"));}).create();
  checkoutDialog.setOnDismissListener(d->{if(i.optString("state").equals("awaiting_confirmation")){GoalStore.put(i,"state","draft");try{store.save("intents",gid,i);}catch(IllegalArgumentException deleted){}}checkoutDialog=null;});checkoutDialog.show();
 }
 void people(){LinearLayout p=card();p.addView(txt("같은 방향으로 가는 사람들",23,INK,true));note(p,"아직 공개된 누비 이용자가 없어. 실제 사용자 프로필을 연결하는 서버·실시간 매칭은 준비 중이야. 외부 모임의 실제 목록을 먼저 찾아볼 수 있어.");action(p,"문토 모임 탐색",()->discover("munto",preset.match,""));action(p,"Meetup 모임 탐색",()->discover("meetup",preset.match,""));action(p,"카카오맵에서 모일 장소 찾기",()->discover("kakaomap",preset.match,""));action(p,"내 공개 프로필 설정 (기기 내 초안)",()->{LinearLayout a=Ui.vertical(this,BG,16);EditText name=edit(a,"닉네임","");CheckBox consent=new CheckBox(this);consent.setText("닉네임·선택한 목표 공개에 동의 (현재 기기에만 저장)");a.addView(consent);new AlertDialog.Builder(this).setTitle("공개 프로필 초안").setView(a).setNegativeButton("취소",null).setNeutralButton("공개 철회",(d,w)->{for(JSONObject row:store.list("profiles",gid))store.remove("profiles",gid,row.optString("id"));toast("초안을 삭제했어.");}).setPositiveButton("초안 저장",(d,w)->{String n=name.getText().toString().trim();if(!consent.isChecked()||n.isEmpty()||n.length()>30){toast("닉네임과 공개 동의를 확인해줘.");return;}JSONObject row=new JSONObject();GoalStore.put(row,"id",gid+"-profile");GoalStore.put(row,"nickname",n);GoalStore.put(row,"goalTitle",g.optString("title"));GoalStore.put(row,"consent",true);GoalStore.put(row,"published",false);store.save("profiles",gid,row);toast("기기에만 저장했어. 외부 공개는 아직 지원하지 않아.");}).show();});
  for(JSONObject c:store.list("contents",gid))if(c.optString("kind").equals("모임")){LinearLayout r=card();r.addView(txt(c.optString("title"),18,INK,true));note(r,c.optString("provider")+" · 외부 모임 후보 / 참가·매칭 전");action(r,"모임 원문 확인",()->open(c.optString("url")));action(r,"후보 숨김·기기 기록 삭제",()->{store.remove("contents",gid,c.optString("id"));render();});}}
 void calendar(){LinearLayout p=card();p.addView(txt("목표를 오늘의 행동으로",23,INK,true));action(p,"일정·할 일 추가",()->taskDraft(null));action(p,"목표에 맞는 실행 사이트",()->open(preset.tool));if(preset.id.equals("grades")){action(p,"UNIST 공식 학사일정",()->startActivity(new Intent(this,UnistCalendarActivity.class)));action(p,"K-MOOC 강의 탐색",()->discover("kmooc",g.optString("topic"),""));}if(preset.id.equals("home")){action(p,"울산 아파트 정보 검색",()->discover("realestate","울산 아파트",""));action(p,"청약홈 공식 일정·공고",()->open("https://www.applyhome.co.kr/"));}action(p,"기존 할 일 보관함",()->startActivity(new Intent(this,TaskActivity.class)));
  try(Cursor c=tasks.getReadableDatabase().rawQuery("SELECT _id,title,state,source_url,due FROM tasks WHERE goal_id=? ORDER BY updated DESC",new String[]{gid})){while(c.moveToNext()){long id=c.getLong(0);String title=c.getString(1),state=c.getString(2),source=c.getString(3),due=c.getString(4);LinearLayout row=card();row.addView(txt(title,18,INK,true));note(row,state+" · "+(due==null?"일정 미지정":due)+" · Asia/Seoul");if(source!=null&&!source.isEmpty())action(row,"일정 출처 보기",()->open(source));action(row,"수정",()->editTask(id,title,due));action(row,"완료 상태 바꾸기",()->{ContentValues v=new ContentValues();v.put("state",state.equals("완료")?"대기":"완료");v.put("updated",System.currentTimeMillis());tasks.getWritableDatabase().update("tasks",v,"_id=? AND goal_id=?",new String[]{Long.toString(id),gid});render();});action(row,"일정 삭제",()->{tasks.getWritableDatabase().delete("tasks","_id=? AND goal_id=?",new String[]{Long.toString(id),gid});render();});}}
 }
 void editTask(long id,String title,String due){LinearLayout p=Ui.vertical(this,BG,16);EditText t=edit(p,"할 일",title),date=edit(p,"날짜 YYYY-MM-DD",due==null?"":due);new AlertDialog.Builder(this).setTitle("일정 수정").setView(p).setNegativeButton("취소",null).setPositiveButton("저장",(d,w)->{try{String text=t.getText().toString().trim(),day=date.getText().toString();if(text.isEmpty()||text.length()>150)throw new Exception();if(!day.isEmpty())java.time.LocalDate.parse(day);ContentValues v=new ContentValues();v.put("title",text);v.put("due",day);v.put("updated",System.currentTimeMillis());tasks.getWritableDatabase().update("tasks",v,"_id=? AND goal_id=?",new String[]{Long.toString(id),gid});render();}catch(Exception e){toast("할 일과 날짜를 확인해줘.");}}).show();}
 void taskDraft(JSONObject c){LinearLayout p=Ui.vertical(this,BG,16);EditText title=edit(p,"할 일",c==null?g.optString("title"):c.optString("title")),due=edit(p,"날짜 YYYY-MM-DD (선택)",java.time.LocalDate.now(java.time.ZoneId.of("Asia/Seoul")).toString());note(p,"출처: "+(c==null?"직접 입력":c.optString("url")));new AlertDialog.Builder(this).setTitle("목표 일정 초안 확인").setView(p).setNegativeButton("취소",null).setPositiveButton("기기에 추가",(d,w)->{try{String text=title.getText().toString().trim(),date=due.getText().toString();if(text.isEmpty()||text.length()>150)throw new Exception();if(!date.isEmpty())java.time.LocalDate.parse(date);ContentValues v=new ContentValues();v.put("title",text);v.put("kind","목표 실행");v.put("state","대기");v.put("updated",System.currentTimeMillis());v.put("goal_id",gid);v.put("source_url",c==null?"":c.optString("url"));v.put("due",date);tasks.getWritableDatabase().insertOrThrow("tasks",null,v);toast("목표에 연결해 저장했어.");tab=3;GoalStore.put(g,"tab",3);store.saveGoal(g);render();}catch(Exception e){toast("할 일 150자 이내와 날짜를 확인해줘.");}}).show();}
 void discover(String provider,String q,String nid){Intent i=new Intent(this,GoalDiscoveryActivity.class);i.putExtra("goal_id",gid);i.putExtra("provider",provider);i.putExtra("query",q);i.putExtra("need_id",nid);store.event(gid,"comparison_started");startActivity(i);}
 protected void onPause(){if(g!=null&&scroll!=null)try{g=store.goal(gid);GoalStore.put(g,"tab",tab);GoalStore.put(g,"scroll"+tab,scroll.getScrollY());store.saveGoal(g);}catch(IllegalArgumentException deleted){}super.onPause();}
 protected void onDestroy(){if(checkoutDialog!=null)checkoutDialog.dismiss();if(tasks!=null)tasks.close();if(store!=null)store.close();super.onDestroy();}
}
